#!/usr/bin/env python3
"""Original Notebook: %run Lain-Zip-Conditional-Learning-Final.py
96 expected-return meta steps, 32 genuine free-proposal REINFORCE slots,
matched zero controls, persistent student-written ZIP revision and frozen reuse.
All code is embedded and can be extracted; no online model download is performed.
"""
import argparse
import base64
import gzip
import hashlib
import html
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import time
import uuid
import zipfile

WORK=Path('/mnt/workspace/lain-zip-pilot')
SOURCE=WORK/'zip-reflection-reward-e1828281'
STUDENT=WORK/'models/Apertus-v1.1-0.5B-Instruct'
OLD_TOOLS=WORK/'zip-reward-gate-fix-a9e201cf/tools'
STUDENT_PYTHON=WORK/'student-env/bin/python'
PROTOCOL='lain-zip-self-conditioned-counterexample-v24'
PAYLOAD=''
PAYLOAD_SHA256='9e4ffb1a2d3e820a3c5c170134cfc8ae3e5cf10124a5d6925287862d891b177a'


def arguments():
    args=list(sys.argv[1:]);clean=[];i=0
    while i<len(args):
        v=args[i]
        if Path(sys.argv[0]).name=='ipykernel_launcher.py' and v=='-f' and i+1<len(args):i+=2;continue
        if Path(sys.argv[0]).name=='ipykernel_launcher.py' and v.startswith('-f='):i+=1;continue
        clean.append(v);i+=1
    return clean


def decode():
    raw=gzip.decompress(base64.b64decode(PAYLOAD))
    if hashlib.sha256(raw).hexdigest()!=PAYLOAD_SHA256:raise RuntimeError('Incomplete code payload')
    modules=json.loads(raw)
    if any(Path(name).name!=name or not name.endswith(('.py','.json')) for name in modules):
        raise ValueError('Invalid bundle filename')
    return modules


def extract_bundle(folder):
    folder=Path(folder);folder.mkdir(parents=True,exist_ok=True)
    for name,content in decode().items():
        path=folder/name
        if path.exists() and path.read_text(encoding='utf-8')!=content:
            raise ValueError('Refuse to overwrite differing source file: '+str(path))
        path.write_text(content,encoding='utf-8')


def previous(source):
    found=[]
    for path in WORK.glob('zip-conditional-final-*/protocol.json'):
        try:value=json.loads(path.read_text())
        except (OSError,ValueError):continue
        if value.get('protocol')==PROTOCOL and value.get('payloadSha256')==PAYLOAD_SHA256 and \
            value.get('source')==str(source):
            found.append((value['createdAt'],str(path.parent),path.parent))
    return max(found)[2] if found else None


def export_review(folder):
    folder=Path(folder).resolve();protocol=json.loads((folder/'protocol.json').read_text())
    if protocol.get('protocol')!=PROTOCOL:raise ValueError('Only this reflection reward experiment may be exported')
    result_path=folder/'result.json' if (folder/'result.json').is_file() else folder/'partial-result.json'
    if not result_path.is_file():raise ValueError('No durable result yet; wait for completion or a saved pause')
    if json.loads(result_path.read_text()).get('protocol')!=PROTOCOL:raise ValueError('Result protocol changed')
    archive=Path.cwd()/('Lain-Zip-Conditional-Learning-Review-'+folder.name.split('-')[-1]+'.zip')
    temp=archive.with_name(archive.name+'.'+uuid.uuid4().hex+'.tmp')
    try:
        with zipfile.ZipFile(temp,'x',zipfile.ZIP_DEFLATED) as z:
            for path in sorted(folder.rglob('*')):
                if path.is_symlink():raise ValueError('Symlink in review output')
                if path.is_file() and path.suffix in ('.json','.txt','.log','.html'):
                    z.write(path,str(path.relative_to(folder)))
        with zipfile.ZipFile(temp) as z:
            if z.testzip() is not None or not {'protocol.json',str(result_path.relative_to(folder))}<=set(z.namelist()):
                raise RuntimeError('Review ZIP integrity failure')
            if any(n.endswith(('.safetensors','.pt','.bin')) for n in z.namelist()):
                raise RuntimeError('Weight or optimizer was included in review ZIP')
        os.replace(temp,archive)
    finally:
        if temp.exists():temp.unlink()
    print('审阅 ZIP：'+str(archive)+'（已校验；不含权重；包含真实原文和笔记版本）',flush=True)
    try:
        from IPython.display import FileLink,HTML,display
        display(FileLink(archive.name,result_html_prefix='下载： '))
        if archive.stat().st_size<=8*1024*1024:
            encoded=base64.b64encode(archive.read_bytes()).decode('ascii')
            display(HTML('<a download="'+html.escape(archive.name,quote=True)+'" href="data:application/zip;base64,'+encoded+'">直接下载条件学习审阅 ZIP</a>'))
    except ImportError:pass
    return archive


def print_result(result):
    if not result:return
    if result.get('fixtureOnly'):raise RuntimeError('Fixture-only result is not a real student experiment')
    if not result.get('complete'):
        print('尚未完成；再次运行接上已提交步骤。原因：'+str(result.get('error')),flush=True);return
    print('完成：meta提交 '+str(result['metaCommitted'])+'，参数改变 '+str(result['metaParameterChanges'])+
        '；editor提交 '+str(result['editorCommitted'])+'，有效反例轮 '+str(result['eligibleEditorEpisodes'])+
        '，参数改变 '+str(result['editorParameterChanges'])+'；零奖励组参数改变 '+str(result['zeroRewardParameterChanges'])+'。',flush=True)
    for collection,arms in result['summary'].items():
        for arm,view in arms.items():
            print(collection+' '+arm+'：正确动作 '+str(view['correctActions'])+'/'+str(view['cases'])+
                '；亲算有效冲突 '+str(view['groundedConflicts'])+'；新证据触发撤回 '+str(view['evidenceTriggeredWithdrawals'])+
                '；学生正确新公式 '+str(view['acceptedStudentProposals'])+'；候选闭环 '+str(view['fullLoopCandidates'])+
                '；误撤回真规则 '+str(view['trueRuleFalseWithdrawals']),flush=True)
    for row in result['rows']:
        if row['collection']=='sourceReadback' and row['arm']=='rewarded' and row['kind']=='counterexample':
            print('真实435旧错卡：'+str(row['beforeAction'])+' → '+str(row['afterAction'])+
                '；亲算 '+json.dumps(row['props'],ensure_ascii=False)+'；候选闭环 '+str(row['fullLoopCandidate']),flush=True)
            print('学生新公式原文：'+row.get('proposal',{}).get('raw','未写'),flush=True)
            print('学生自由反思原文（须人工检查）：'+row.get('ownReflection',{}).get('raw','未写'),flush=True)
    print('435明确进入TRAIN；全新规则单独报告。符号与动作受约束，新公式自由生成；程序奖励和形式核验均明确披露。',flush=True)
    print('只检验针对性条件学习的存在证据；不声称普遍鲁棒性、无提示反省或统计显著性。',flush=True)


def run_main():
    parser=argparse.ArgumentParser(description='学生亲算反例、条件化撤回、新公式奖励和持久化复用')
    parser.add_argument('--self-test',action='store_true');parser.add_argument('--require-torch',action='store_true')
    parser.add_argument('--extract-only',type=Path);parser.add_argument('--export-only',action='store_true')
    parser.add_argument('--source',type=Path,default=SOURCE)
    parser.add_argument('--resume',type=Path);parser.add_argument('--new',action='store_true')
    parser.add_argument('--meta-steps',type=int);parser.add_argument('--editor-steps',type=int);parser.add_argument('--quick',action='store_true')
    parser.add_argument('--meta-lr',type=float);parser.add_argument('--editor-lr',type=float);parser.add_argument('--seconds',type=float,default=10800)
    args=parser.parse_args(arguments())
    if args.new and args.resume:raise ValueError('--new and --resume cannot be combined')
    if not 60<=args.seconds<=10800:raise ValueError('Time limit must be 60..10800 seconds')
    if args.extract_only:
        extract_bundle(args.extract_only);print('可读源码已展开：'+str(args.extract_only.resolve()));return args.extract_only,None
    if args.self_test:
        with tempfile.TemporaryDirectory(prefix='lain-reflection-reward-check-') as folder:
            extract_bundle(folder)
            command=[sys.executable,'-B',str(Path(folder)/'cf_checks.py')]
            if args.require_torch:command.append('--require-torch')
            status=subprocess.run(command,cwd=folder)
            if status.returncode:raise RuntimeError('Offline preflight failed')
        return None,None
    source=args.source.resolve()
    out=args.resume.resolve() if args.resume else (None if args.new else previous(source))
    if args.export_only:
        if out is None:raise ValueError('No experiment found; use --resume to specify its directory')
        export_review(out);return out,None
    if out is not None:
        protocol=json.loads((out/'protocol.json').read_text())
        if protocol.get('protocol')!=PROTOCOL or protocol.get('payloadSha256')!=PAYLOAD_SHA256 or \
            protocol.get('source')!=str(source):
            raise ValueError('Resume source or code payload does not match')
        recipe=protocol['recipe']
        fields=[('meta_steps','metaSteps'),('editor_steps','editorSteps'),('meta_lr','learningRate'),('editor_lr','editorLearningRate')]
        for attr,key in fields:
            value=getattr(args,attr)
            if value is not None and value!=recipe[key]:raise ValueError('Cannot change frozen recipe on resume: '+attr)
        if args.quick and not recipe['quick']:raise ValueError('Cannot change curriculum on resume')
        meta_steps=recipe['metaSteps'];editor_steps=recipe['editorSteps'];meta_lr=recipe['learningRate'];editor_lr=recipe['editorLearningRate'];quick=recipe['quick']
        if (out/'result.json').is_file():
            result=json.loads((out/'result.json').read_text())
            if result.get('complete'):
                print('已有完整结果，重新导出下载；不重复更新、不再加载学生。',flush=True)
                print_result(result);export_review(out);return out,result
    else:
        meta_steps=args.meta_steps if args.meta_steps is not None else (16 if args.quick else 96)
        editor_steps=args.editor_steps if args.editor_steps is not None else (4 if args.quick else 32)
        meta_lr=args.meta_lr if args.meta_lr is not None else .0005
        editor_lr=args.editor_lr if args.editor_lr is not None else .0001;quick=args.quick
    if not 1<=meta_steps<=192 or not 0<=editor_steps<=64 or not 0<meta_lr<=.001 or not 0<editor_lr<=.001:
        raise ValueError('Meta 1..192; editor 0..64; learning rates (0,.001]')
    for path in (source/'protocol.json',source/'committed/step-0064/reflection.safetensors',STUDENT/'config.json',
        OLD_TOOLS/'zip_pilot.py',OLD_TOOLS/'zip_pilot_model.py',STUDENT_PYTHON):
        if not path.is_file():raise RuntimeError('请在原训练 Notebook 运行；缺少：'+str(path))
    suffix=uuid.uuid4().hex[:8];runtime=WORK/('zip-conditional-final-tools-'+suffix)
    out=out or WORK/('zip-conditional-final-'+suffix);extract_bundle(runtime)
    env=dict(os.environ,PYTHONPATH=os.pathsep.join([str(runtime),str(OLD_TOOLS)]),PYTHONSAFEPATH='1',
        PYTHONDONTWRITEBYTECODE='1',PYTHONUNBUFFERED='1',HF_HUB_OFFLINE='1',TRANSFORMERS_OFFLINE='1',
        USE_TORCH='1',USE_TF='0',USE_FLAX='0')
    original_path=list(sys.path);sys.path.insert(0,str(runtime));monitor=None
    try:
        from cf_launch import LaunchMonitor,run_child
        monitor=LaunchMonitor(args.seconds);monitor.phase('离线题库、真实小模型梯度和事务恢复检查；尚未加载学生')
        status=run_child([str(STUDENT_PYTHON),'-B',str(runtime/'cf_checks.py'),'--require-torch'],env,monitor,
            log_path=runtime/'preflight.log')
        if status['paused']:return None,None
        if status['exitCode']:
            print((runtime/'preflight.log').read_text()[-7000:]);raise RuntimeError('Mandatory preflight failed; actual student not loaded')
        print((runtime/'preflight.log').read_text()[-650:],flush=True)
        print('本轮来源：'+str(source)+'；结果目录：'+str(out),flush=True)
        print('默认46个TRAIN情形、24个隔离测试情形（12条不同规则）、4个真实旧卡检查；435旧错卡明确进入TRAIN。',flush=True)
        print('meta '+str(meta_steps)+'提交槽；editor '+str(editor_steps)+'提交槽；同初始零奖励对照。只有有效亲算反例与实际撤回才生成新公式训练。',flush=True)
        print('符号／因子受约束工具选择；新公式96token自由生成；自由反思128token；最多480次原文、8192条选择。不给正确替换公式。',flush=True)
        monitor.phase('真实学生加载、历史冷重放、条件化撤回与自由新公式奖励训练')
        command=[str(STUDENT_PYTHON),'-B','-u',str(runtime/'cf_run.py'),
            '--source',str(source),'--out',str(out),'--work',str(WORK),
            '--student',str(STUDENT),'--old-tools',str(OLD_TOOLS),'--payload',PAYLOAD_SHA256,
            '--meta-steps',str(meta_steps),'--editor-steps',str(editor_steps),
            '--meta-lr',str(meta_lr),'--editor-lr',str(editor_lr),
            '--seconds',str(max(60.,monitor.deadline-time.monotonic())),'--live',str(runtime/'live.json')]
        if quick:command.append('--quick')
        status=run_child(command,env,monitor,log_path=runtime/'student-child.log',live=runtime/'live.json')
        if (out/'protocol.json').is_file():
            # Do not harvest or overwrite another still-running experiment's state.
            if status['exitCode'] and 'Another process is already running' in (runtime/'student-child.log').read_text():
                raise RuntimeError('该实验已有进程在运行；没有启动重复训练。')
            shutil.copyfile(runtime/'student-child.log',out/('child-output-'+suffix+'.log'))
            shutil.copyfile(runtime/'preflight.log',out/('preflight-'+suffix+'.log'))
            (out/('launcher-status-'+suffix+'.json')).write_text(json.dumps(status,ensure_ascii=False,indent=2),encoding='utf-8')
            from cf_store import partial
            if not (out/'result.json').is_file() and not (out/'partial-result.json').is_file():
                partial(out,status['reason'] or 'Child stopped; resume durable state')
            path=out/'result.json' if (out/'result.json').is_file() else out/'partial-result.json'
            result=json.loads(path.read_text());print_result(result);export_review(out)
            if status['exitCode'] and not status['paused']:
                print('子进程异常已包含在审阅包；错误日志：'+str(out/('child-output-'+suffix+'.log')),flush=True)
            return out,result
        print((runtime/'student-child.log').read_text()[-7000:],flush=True)
        raise RuntimeError('来源检查或加载前中止；日志：'+str(runtime/'student-child.log'))
    finally:
        if monitor is not None:monitor.close()
        sys.path[:]=original_path


if __name__=='__main__':
    ZIP_CONDITIONAL_OUTPUT,ZIP_CONDITIONAL_RESULT=run_main()
